//! Compare synthetic open-result projection to twenty retained source rows.
use spore_core::cell_stream_open_result_v1::{project,Fields};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native rows")).unwrap();assert_eq!(b.len(),1120);let cases=[(0,1,3,1,0,u32::MAX,87),(u32::MAX,0,3,1,0,u32::MAX,87),(u32::MAX,1,6,1,0,u32::MAX,87),(u32::MAX,2,6,2,0,0x01020304,99),(u32::MAX,3,1,3,1,0x01020304,99),(u32::MAX,1,2,0,2,0,99),(u32::MAX,2,3,2,3,u32::MAX,5),(u32::MAX,3,4,1,0,0x01020304,99),(u32::MAX,1,5,2,1,0x01020304,99),(u32::MAX,2,9,3,2,0x01020304,99)];let f=Fields{f214:0xa5a5a5a5,f218:0xa5a5a5a5,f21c:0xa5a5a5a5,f220:0xa5a5a5a5,f224:0xa5a5a5a5,f228:0xa5a5a5a5};
 for i in 0..20{let(h,a,m,s,fl,result,error)=cases[i%10];let x=project(h,a,m,s,fl,f,Some(result),Some(error),true).unwrap();let r=&b[i*56..(i+1)*56];let z=x.fields;assert_eq!([w(r,0),w(r,4),w(r,8),w(r,12),w(r,16),w(r,20),w(r,24),w(r,28),w(r,32),w(r,36)],[u32::from(x.returned),x.handle,z.f214,z.f218,z.f21c,z.f220,z.f224,z.f228,x.create_calls,x.error_calls]);let fp=w(r,40);assert_eq!(fp&0xffff,if i>=10{0x37f}else{0x27f});assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(r,44)&!0x3f,0x1f80);assert_eq!((w(r,48),w(r,52)),(0xc0dec0de,0xa5a5a5a5));}println!("matched twenty synthetic open-result source rows; no OS file call");}
